import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷天大壯","description":"周易折中 - 雷天大壯","frontmatter":{"title":"雷天大壯","description":"周易折中 - 雷天大壯"},"headers":[],"relativePath":"classics/zhezhong/040.md","filePath":"classics/zhezhong/040.md"}'),h={name:"classics/zhezhong/040.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="雷天大壯" tabindex="-1">雷天大壯 <a class="header-anchor" href="#雷天大壯" aria-label="Permalink to “雷天大壯”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>大壯序卦曰：遁者，退也。物不可以終遁，故受之以大壯。遁為違去之義，壯為進盛之義。遁者，陰長而陽遁也。大壯，陽之壯盛也。衰則必盛，消息相須，故既遁則必壯。大壯所以次遁也。為卦震上幹下，乾剛而震動，以剛而動，大壯之義也。剛陽大也，陽長已過中矣，大者壯盛也。又雷之威震而在天上，亦大壯之義也。</p><p>大壯：利貞</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>大，謂陽也。四陽盛長，故為大壯，二月之卦也。陽壯則佔者吉亨，不假言，但利在正固而已。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>《大壯》之道利於貞正也，《大壯》而不得其正，強猛之為耳，非君子之道壯盛也。</p><p>注意：原文沒有標點符號，此處AI解讀認為並不通順，所以給出以下解讀，可做參考。</p><p>《大壯》之道，利於貞正也。《大壯》而不得其正，強猛之為耳，非君子之道。壯盛也，應依正理而行，方可顯其利。</p><p>象曰：雷在天上，大壯；君子以非禮弗履</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>自勝者強</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>雷震於天上，大而壯也。君子觀大壯之象，以行其壯。君子之大壯者，莫若克己復禮。古人云：“自勝之謂強。”中庸於和而不流，中立而不倚，皆曰“強哉矯”。赴湯火，蹈白刃，武夫之勇可能也；至於克己復禮，則非君子之大壯，不可能也。故云“君子以非禮弗履”。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰：克己反禮，壯莫盛焉。</p></li><li><p>朱子語類雲：雷在天上，是甚生威嚴。人之克己，須是如雷在天上，方能克去非禮。</p></li><li><p>項氏安世曰：君子所以養其剛大者，亦曰“非禮勿履”而已。</p></li></ul><p>彖曰：大壯，大者壯也。剛以動，故壯</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>釋卦名義，以卦體言，則陽長過中，大者壯也。以卦徳言，則乾剛震動，所以壯也。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>所以名大壯者，謂大者壯也。陰為小，陽為大，陽長以盛，是大者壯也。下剛而上動，以幹之，至剛而動，故為大壯，為大者壯與壯之大也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li>項氏安世曰：剛則不為物慾所橈，故其動也壯。使以血氣而動，安得壯乎？</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>大者謂陽也，大者壯謂四陽盛長也。此句正釋名卦之義。剛以動故壯，一句非正釋卦名，乃推明卦之善以起辭義耳。凡曰“故”者，皆同義，如“順以說，故聚”，“明以動，故豐”是也。</p><p>大壯，利貞。大者正也，正大而天地之情可見矣</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>釋“利貞”之義而極言之。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>大者既壯，則利於貞正。正而大者，道也。極正大之理，則天地之情可見矣。天地之道，常久而不已者，至大至正也。正大之理，學者黙識心通可也。不雲“大正”而云“正大”，恐疑為一事也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類問 ：如何見天地之情？曰：正大便見得天地之情。天地只是正大，未嘗有些子邪處。</p></li><li><p>胡氏炳文曰 ：心未易見，故疑其辭曰“復其見天地之心乎？”情則可見矣，故直書之。孟子養氣之論，自此而出。大者壯也，即是其為氣也至大至剛；大者正也，即是以直養而無害。</p></li></ul><p>初九：壯於趾，徵兇，有孚</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>趾在下而進動之物也。剛陽處下而當壯時，壯於進者也，故有此象。居下而壯於進，其兇必矣，故其佔又如此。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>初陽剛乾體而處下，壯於進者也。在下而用壯，壯於趾也。趾在下而進力之物，九在下用壯而不得其中。夫以剛處壯，雖居上猶不可行，況在下乎？故徵則其兇。有孚，孚信也，謂以壯往則得兇可必也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：在下而壯，故曰“壯於趾”也。居下而用剛壯，以斯而進，窮兇可必也。故曰“徵兇有孚”。</p></li><li><p>王氏申子曰：卦雖以剛壯為義，然爻義皆貴於用柔。蓋以剛而動剛，不可過也。趾在下而主於行，初幹體而居剛用剛，是壯於行而不顧者也。在上猶為過，況在下乎？其兇必矣。</p></li></ul><p>象曰：壯於趾，其孚窮也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>言必窮困</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>在最下而用壯以行，可必信其窮困而兇也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏申子曰：居下而用壯，任剛而決行，信乎其窮而兇也。</li></ul><p>九二：貞吉</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>以陽居陰，已不得其正矣。然所處得中，則猶可因以不失其正，故戒佔者使因中以求正，然後可以得吉也。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二雖以陽剛當大壯之時，然居柔而處中，是剛柔得中，不過於壯，得貞正而吉也。或曰：“貞非以九居二為戒乎？”曰：“易取所勝為義，以陽剛健體當大壯之時，處得中道，無不正也。”在四則有不正之戒，人能識時義之輕重，則可以學易矣。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：居得中位，以陽居陰，履謙不亢，是以貞吉。</p></li><li><p>易氏祓曰：爻貴得位，大壯則以陽居陰為吉。蓋慮其陽剛之過於壯也，故二與四皆言貞吉。</p></li></ul><p>象曰：九二貞吉，以中也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>所以貞正而吉者，以其得中道也。中則不失正，況陽剛而乾禮乎？</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li>孔氏穎達曰：以其居中履謙，行不違禮，故得正而吉也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>卦言大壯利貞，惟九二剛徳則為大壯，體則為壯，而居中則為處壯之貞，乃卦之主也。故傳言以中明大壯之貞在於中也。</p><p>九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>過剛不中，當壯之時，是小人用壯，而君子則用罔也。罔，無也，視有如無。君子之過於勇者也，如此則雖正亦危矣。羝羊，剛壯喜觸之物；藩籬也；羸，困也。貞厲之佔，其象如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>九三以剛居陽而處壯，又當幹體之終，壯之極者也。極壯如此，在小人則為用壯，在君子則為用罔。小人尚力，故用其壯勇；君子志剛，故用罔。罔，無也，猶雲蔑也，以其至剛，蔑視於事而無所忌憚也。君子小人以地言，如君子有勇而無義為亂。剛柔得中，則不折不屈，施於天下而無不宜；苟剛之太過，則無和順之德，多傷莫與。貞固守此，則危道也。凡物莫不用其壯，齒者齧，角者觸，蹄者踶；羊壯於首，羝為喜觸，故取為象。羊喜觸藩籬，以藩籬當其前也，蓋所當必觸。喜用壯如此，必羸困其角矣，猶人尚剛壯，所當必用，必至摧困也。三壯甚如此，而不至兇，何也？曰：如三之為其往，足以致兇，而方言其危，故未及於兇也。凡可以致兇而未至者，則曰厲也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>京氏房曰：壯一也，小人用之，君子有而不用。</p></li><li><p>劉氏牧曰：罔，不也。君子尚德而不用壯，若固其壯則危矣。</p></li><li><p>胡氏瑗曰：九三處下卦之上，當乾健之極，以陽居陽，是強壯之人也。以小人乘此，則必恃剛強陵犯於人，雖至壯極而不已，是用壯者也。君子則不然，雖壯而不矜，雖大而不伐，罔而不用其壯也。小人居強壯之時，動則過中，進則不顧，是猶剛狠之羊，雖藩在前，亦觸突而進，以至反羸其角，兇之道也。</p></li><li><p>郭氏雍曰：剛至三而壯矣。小人務勝人，故喜壯而用之；君子務勝己之私，是以勿用壯於外也。以用壯為正，則危矣。羊狠喜觸，用壯之象也。觸藩羸角，用壯而厲也。君子用罔者，君子罔以壯為用也。先儒或為羅網之罔，失之矣。</p></li><li><p>項氏安世曰：既曰“小人用壯”，又曰“君子用罔”，勸戒備矣。又曰“貞厲，羝羊觸藩，羸其角”者，恐人以用剛居剛為得正也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>京氏以下諸家說“用罔”與傳義異，以夫子小象文意參之，諸說近是。</p><p>象曰：小人用壯，君子罔也</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>小人以壯敗，君子以罔困</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>在小人則為用其強壯之力，在君子則為用罔（無）。志氣剛強，蔑視於事，靡所顧憚也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰：君子用罔，說者不同。然觀爻辭之例，如“小人吉，大人否”、“亨，君子吉，小人否”、“婦人吉，夫子兇”，皆是相反之辭。又象辭曰“小人用壯，君子罔也”，全與“君子好遁，小人否也”句法相類。詩書中“罔”字與“弗”字、“勿”字、“毋”字通用，皆禁止之義也。</p></li><li><p>楊氏簡曰：九三益進，勢雖壯，君子之心未嘗以為意焉。唯小人則自喜己勢之壯而益肆益壯，是謂“小人用壯”。罔無也，言君子之所用異乎小人之用也，故曰“小人用壯，君子罔也”。</p></li><li><p>龔氏煥曰：大壯本以四陽盛長而得名，九三又以陽居陽而過剛，壯而又壯者也。用壯如此，是小人之所為，而非君子之道，故曰“君子用罔”。象釋之曰“小人用壯，君子罔也”，語意與遁九四“君子好遁，小人否也”同。蓋遁之九四即大壯九三之反對，皆君子小人並言。</p></li><li><p>俞氏琰曰：孔子恐後世疑爻辭有兩“用”字，以為小人之用與君子同，故特去其一。</p></li></ul><p>九四：貞吉悔亡，藩決不羸，壯於大輿之輹</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>貞吉悔亡，與鹹九四同佔。藩決不羸，承上文而言也。決，開也。三前有四，猶有藩焉；四前二陰，則藩決矣。壯於大輿之輹，亦可進之象也。以陽居陰，不極其剛，故其象佔如此。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四陽剛長，盛壯已過中，壯之甚也。然居四為不正方，君子道長之時，豈可有不正也？故戒以貞則吉而悔亡。蓋方道長之時，小失則害亨進之勢，是有悔也。若在他卦，重剛而居柔，未必不為善也，大過是也。藩所以限隔也，藩籬決開，不復羸困其壯也。髙大之車輪輹，強壯其行之利可知，故云“壯於大輿之輹”。輹，輪之要處也，車之敗常在折輹，輹壯則車強矣。雲“壯於輹”，謂壯於進也。輹與輻同。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：未有違謙越禮而能全其壯者也。故陽爻皆以居陰位為美。</p></li><li><p>鄭氏汝諧曰：居四陽之終，其壯易過，故必正吉則悔亡。群陽並進，非二陰之所能止，藩決不羸，其道通也。壯於大輿之輹，其行健也。</p></li><li><p>朱子語類雲：九二貞吉只是自守而不進，九四卻是有可進之象。蓋以陽居陰，不極其剛，而前遇二陰，有藩決之象，所以為進，非如九二前有三四二陽隔之不得進也。</p></li><li><p>俞氏琰曰：爻剛位柔，不極其壯，故因佔設戒曰“貞吉悔亡”。三以九四之剛在前，如藩籬之障而不能進，故觸而受羸；四以六五之柔在前，如藩籬剖破而無俟乎觸，故不羸。曰“藩決不羸”，而不及羊，承九三之辭也。</p></li></ul><p>象曰：藩決不羸，尚往也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>剛陽之長必至於極，四雖已盛，然其往未止也。以至盛之陽用壯而進，故莫有當之。藩決開而不羸困其力也，尚往其進不已也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>項氏安世曰：九四以剛居柔，有能正之吉，無過剛之悔。“貞吉悔亡”四字既盡之矣。又曰“藩決不羸”，壯於大輿之輹者，恐人以居柔為不進也，故以“尚往”明之。</li></ul><p>六五：喪羊於易，無悔</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>卦體似兌，有羊象焉。外柔而內剛者也，獨六五以柔居中，不能牴觸，雖失其壯，然亦無所悔矣。故其象佔如此。易，容易之易，言忽然不覺其亡也；或作疆埸之埸，亦通（漢食貨志“埸”作“易”）。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>羊群行而喜觸，以象諸陽並進。四陽方長而並進，五以柔居上，若以力制則難勝而有悔，惟和易以待之，則群陽無所用其剛，是喪其壯於和易也。如此則可以無悔。五以位言則正，以德言則中，故能用和易之道，使群陽雖壯無所用也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類雲：“喪羊於易”不若作“疆埸之易”（漢食貨志“疆埸”之“埸”正作“易”）。蓋後面有“喪牛於易”，亦同此義。今《本義》所注只是從前所說如此，只且仍舊耳。</p></li><li><p>胡氏炳文曰：旅上九“喪牛於易”，牛性順，上九以剛居極，不覺失其所謂順；此曰“喪羊於易”，羊性剛，六五以柔居中，不覺失其所謂剛，自失其壯，故爻獨不言壯。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>壯之道貴乎得中。九二方壯之時，以剛處中，壯之正也；至六五，則壯已過矣，又以柔處中，則無所用其壯矣。故雖喪羊而無悔。</p><p>象曰：喪羊於易，位不當也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>所以必用柔和者，以陰柔居尊位故也。若以陽剛中正得尊位，則下無壯矣。以六五位不當也，故設“喪羊於易”之義。然大率治壯不可用剛，夫君臣上下之勢不相侔也。苟君之權足以制乎下，則雖有強壯跋扈之人，不足謂之壯也。必人君之勢有所不足，然後謂之治壯。故治壯之道不可以剛也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏安石曰：剛柔者所以立本，變通者所以趨時。方其趨時，則位正當而有咎兇，位不當而無悔者有矣。大壯之時，得中而處之以柔，能喪其很者也。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>位當位不當，易例多借爻位以發明其德與時地之相當不相當也。此位不當，不止謂以陰居陽不任剛壯而已，蓋謂四陽已過矣，則五所處非當壯之位也。於是而以柔中居之，故為“喪羊於易”。</p><p>上六：羝羊觸藩，不能退，不能遂，無攸利，艱則吉</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>壯終動極，故觸藩而不能退，然其質本柔，故又不能遂其進也。其象如此，其佔可知。然猶幸其不剛，故能艱以處，則尚可以得吉也。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>羝羊但取其用壯，故陰爻亦稱之。六以陰處震終而當壯，極其過可知，如羝羊之觸藩籬，進則礙身，退則妨角，進退皆不可也。才本陰柔，故不能勝已以就義，是不能退也。陰柔之人，雖極用壯之心，然必不能終其壯，有摧必縮，是不能遂也。其所為如此，無所往而利也。陰柔處壯，不能固其守，若遇艱困，必失其壯，失其壯則反得柔弱之分矣。是艱則得吉也。用壯則不利，知艱而處柔則吉也。居壯之終，有變之義也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類雲：上六取喻甚巧，蓋壯終動極，無可去處，如羝羊之角掛於藩上，不能退遂。然“艱則吉”者，畢竟有可進之理，但必艱始吉耳。</p></li><li><p>易氏祓曰：三前有四，故為觸藩；四前遇陰，故為藩決。上六前無滯礙，而亦言觸藩者，處一卦之窮也。不能退者，在眾爻之上；不能遂者，亢而不可前進也。然能艱則吉，此《易》之所以備勸戒也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>五與上皆陰爻而當陽壯已過之時，五猶曰“喪羊”，而上反曰“羝羊觸藩”，何也？蓋《易》者，像也。羊之觸也，以角。卦似兌，有羊象，而上六適當角位，故雖陰爻而亦云觸藩也。陰柔不至於羸角，但不能退、不能遂而已。艱則吉者，知其難而不敢輕易以處之也，故可進則進，不可進則退。雜卦謂“大壯則止”，是也。</p><p>象曰：不能退，不能遂，不詳也；艱則吉，咎不長也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>非其處而處，故進退不能，是其自處之不詳慎也。艱則吉，柔遇艱難，又居壯終，自當變矣。變則得其分，過咎不長，乃吉也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏炳文曰：臨卦六三與大壯上六皆言“無攸利”，皆曰“咎不長”。蓋六三之憂與上六之艱，不貴無過，而貴改過也。</p></li><li><p>俞氏琰曰：人之處事，以為易則不詳審，以為艱則詳審。向也既以不詳審而致咎，今詳審而不輕率，則其咎不長也。</p></li></ul><p>總論</p><p>項氏安世曰：有以事理得中為正者，有以陰陽當位為正者。剛以柔濟之，柔以剛濟之，使不失其正，此事理之正也。以剛處剛，以柔處柔，各當其位，此爻位之正也。大壯之時義，其所謂“利貞”者，利守事理之正，不以爻位言也。是故九二、九四、六五三爻不當位而皆利，初九、九三、上六三爻當位而皆不利。又於九二、九四爻辭明言“貞吉”，於初九、九三爻辭明言“徵兇”、“貞厲”，聖人猶恐其未明也，又以小象釋之。於九二則曰“九二貞吉，以中也”，明正吉以中而不以位也；於六五則曰“位不當也”，亦明無悔在中不在位也。《易》之時義屢遷，如此。</p>',121)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
